public int findLargestSubstring(List<String> strings) {
    // Sort the strings by length in descending order
    strings.sort(Comparator.comparingInt(String::length).reversed());

    // Initialize the largest substring found so far
    int largestSubstring = 0;

    // Iterate over the strings in descending order of length
    for (String string : strings) {
        // Check if the current string is a substring of any of the other strings
