    private static Set<Set<Integer>> findSquarePairs(int[] A) {
        Set<Set<Integer>> squarePairs = new HashSet<>();
        for (int i = 0; i < A.length - 1; i++) {
            int sum = A[i] + A[i + 1];
            int root = (int) Math.sqrt((double) sum);
            if (root * root == sum) {
                Set<Integer> pair = new HashSet<>();
                pair.add(A[i]);
                pair.add(A[i + 1]);
                squarePairs.add(pair);
            }
        }
        return squarePairs;
    }

    private static void generatePermutations(int[] A, Set<Integer> permutations, int start, int end,
            Set<Set<Integer>> squarePairs) {
        if (start == end) {
            permutations.addAll(squarePairs);
        } else {
            for (int i = start; i <= end; i++) {
                Set<Integer> pair = new HashSet<>();
                pair.add(A[i]);
                pair.add(A[start]);
                if (squarePairs.contains(pair)) {
                    generatePermutations(A, permutations, start + 1, end, squarePairs);
                }
            }
        }
    }
